+  if (rank <= 53) return 13;
+  if (rank <= 83) return 14;
+  return 15;
+}
+
+function addIndex(index, key, companyId) {
+  if (!key) return;
+  if (!index.has(key)) index.set(key, new Set());
+  index.get(key).add(companyId);
